// @vitest-environment jsdom
import { beforeEach, afterEach, describe, expect, it, vi } from 'vitest'
const bridge = vi.hoisted(() => vi.fn())
vi.mock('@tauri-apps/api/core', () => ({ invoke: bridge }))
beforeEach(() => { vi.resetModules(); bridge.mockReset(); localStorage.clear(); Object.defineProperty(window, '__TAURI_INTERNALS__', { value: {}, configurable: true }) })
afterEach(() => { Reflect.deleteProperty(window, '__TAURI_INTERNALS__') })
describe('encrypted document bridge', () => {
  it('reports an outdated native app instead of incorrectly asking to unlock the keychain', async () => {
    const store = await import('../../src/services/security/secureStore')
    bridge.mockRejectedValue(new Error('Command secure_document_read not found'))
    await expect(store.readSecureDocument('agent_chats')).rejects.toThrow()
    expect(store.secureStorageState.error).toContain('版本不一致')
    expect(store.secureStorageState.error).not.toContain('钥匙串')
    await expect(store.writeSecureDocument('agent_chats', [])).rejects.toThrow('阻止覆盖')
  })
  it('never authorizes during startup or retries; recovery happens only from an explicit action', async () => {
    const store = await import('../../src/services/security/secureStore')
    bridge.mockRejectedValue(new Error('SECURE_STORAGE_AUTHORIZATION_REQUIRED'))
    await expect(store.readSecureDocument('agent_chats')).rejects.toThrow('AUTHORIZATION_REQUIRED')
    await expect(store.readSecureDocument('model_settings')).rejects.toThrow('AUTHORIZATION_REQUIRED')
    expect(store.secureStorageState.requiresAuthorization).toBe(true)
    await expect(store.writeSecureDocument('agent_chats', [])).rejects.toThrow('阻止覆盖')
    expect(store.secureStorageState.requiresAuthorization).toBe(true)
    expect(bridge.mock.calls.some(([name]) => name === 'secure_storage_authorize')).toBe(false)
    bridge.mockResolvedValueOnce(undefined)
    expect(await store.authorizeSecureStorage()).toBe(true)
    expect(bridge).toHaveBeenLastCalledWith('secure_storage_authorize')
  })
  it('removes a plaintext legacy copy only after native storage acknowledges it', async () => {
    const store = await import('../../src/services/security/secureStore')
    localStorage.setItem('legacy-accounts', JSON.stringify({ password: 'synthetic-password' }))
    bridge.mockRejectedValueOnce(new Error('locked'))
    await expect(store.readSecureDocument('site_accounts', 'legacy-accounts')).rejects.toThrow('locked')
    expect(localStorage.getItem('legacy-accounts')).toContain('synthetic-password')
    bridge.mockResolvedValueOnce({ password: '{{secret:site/example.test/password}}' })
    expect(await store.readSecureDocument('site_accounts', 'legacy-accounts')).toEqual({ password: '{{secret:site/example.test/password}}' })
    expect(localStorage.getItem('legacy-accounts')).toBeNull()
    expect(bridge.mock.calls.at(-1)?.[0]).toBe('secure_document_read')
  })
  it('queues immutable native snapshots and never mirrors their plaintext to localStorage', async () => {
    const store = await import('../../src/services/security/secureStore')
    bridge.mockImplementation(async (_name, args) => args.value)
    const value = { content: 'not-yet-identified-credential' }
    const first = store.writeSecureDocument('agent_chats', value)
    value.content = 'later-message'
    const second = store.writeSecureDocument('agent_chats', value)
    expect(await first).toEqual({ content: 'not-yet-identified-credential' })
    expect(await second).toEqual({ content: 'later-message' })
    expect(localStorage.length).toBe(0)
  })
  it('uses session-only memory in browser previews rather than a plaintext fallback', async () => {
    Reflect.deleteProperty(window, '__TAURI_INTERNALS__')
    const store = await import('../../src/services/security/secureStore')
    await store.writeSecureDocument('model_settings', { apiKey: 'preview-key' })
    expect(await store.readSecureDocument('model_settings')).toEqual({ apiKey: 'preview-key' })
    expect(localStorage.length).toBe(0)
    expect(bridge).not.toHaveBeenCalled()
  })
  it('blocks overwriting unread history and retains its error when another document succeeds', async () => {
    const store = await import('../../src/services/security/secureStore')
    bridge.mockRejectedValueOnce(new Error('locked'))
    await expect(store.readSecureDocument('agent_chats')).rejects.toThrow('locked')
    bridge.mockResolvedValueOnce({})
    await store.readSecureDocument('app_settings')
    expect(store.secureStorageState.error).toBeTruthy()
    await expect(store.writeSecureDocument('agent_chats', [])).rejects.toThrow('阻止覆盖')
    expect(bridge.mock.calls.some(([name]) => name === 'secure_document_write')).toBe(false)
    bridge.mockResolvedValueOnce([{ content: 'preserved' }])
    await store.readSecureDocument('agent_chats')
    expect(store.secureStorageState.error).toBe('')
  })
})
